const messages = { en, da, nl }
export const translator = (locale: Account['locale'] | undefined) => (key: MessageKey): string => messages[locale || 'en'][key]
export const localeTag = (locale: Account['locale'] | undefined): string => ({ en: 'en-GB', da: 'da-DK', nl: 'nl-NL' })[locale || 'en']
export const rememberedLocale = (): Account['locale'] => { const saved = window.localStorage.getItem('madplanner-locale'); if (saved === 'da' || saved === 'nl') return saved; return navigator.language.toLowerCase().startsWith('da') ? 'da' : navigator.language.toLowerCase().startsWith('nl') ? 'nl' : 'en' }
